// Wygenerowane z wyszukiwarki dekorów pfleiderer.com/pl-pl (2026-10-31): 432 dekory, Express = płyta
// laminowana w programie szybkiej dostawy. Miniatury: https://www.pfleiderer.com/file_pim/_processed_/<img>.
enum PfleidererCatalog {
    enum Group: String, CaseIterable {
        case wood, uni, stone, creative
        var label: String {
            switch self {
            case .wood: return "Drewno"
            case .uni: return "Jednobarwne"
            case .stone: return "Kamień"
            case .creative: return "Kreatywne"
            }
        }
    }

    struct D: Identifiable, Hashable {
        let code, name: String
        let group: Group
        let express: Bool
        let img: String
        init(_ code: String, _ name: String, _ group: Group, _ express: Bool, _ img: String) {
            self.code = code; self.name = name; self.group = group; self.express = express; self.img = img
        }
        var id: String { code }
        var imageURL: URL? { img.isEmpty ? nil : URL(string: "https://www.pfleiderer.com/file_pim/_processed_/" + img) }
    }

    static func find(_ code: String?) -> D? { code.flatMap { c in all.first { $0.code == c } } }

